// engine/dw3/equipment.ts
// Real weapon/armor/accessory catalog — decoded 2026-07-04 from ~/ddw3's static disasm
// data (D0x80041844: [Unknown1;402] item table + D0x80040244: [Unknown0;200] equip-stat
// table in rust/dw2003_exe_data/src/data.rs), generated by tools/build_equipment.py.
// Full decode writeup: docs/research/battle/equipment-system-decoded-2026-07-04.md.
//
// slot: which Unknown4Items slot (head/body/right/left/accessory — acc0 and acc1 share
// the "accessory" slot type) an item can be worn in, derived from its ItemId name-range
// in item_id.rs (verified against the Unknown1.f4 family-code column).
//
// family: the Unknown1 byte +0x9 that selects how the stat record is read.
// statBytes: the item's equip-stat record VERBATIM (20-byte Unknown0 for weapons and
// armour, 12-byte Unknown2 for accessories). It is shipped as bytes because the game
// reads it by byte offset and the meaning of an offset changes with the family — see
// `gearStatContributions` below for the shop/status-screen rule (stitshop F0x80088a64)
// and EQUIP-C009 for the two battle pools (accPool/evadePool).

// The catalog itself is GENERATED (tools/build_equipment_ts.py → equipment-data.ts) from
// the Unknown0/1/2 tables — including the 68 decoded accessory effects and the 2026-07-10
// off-by-one fix (Unknown1 row i = ItemId i+1; the old inline array was shifted one item).
export { EQUIPMENT, type EquipmentItem, type AccessoryEffect } from "./equipment-data.ts";
import { EQUIPMENT, type EquipmentItem, type AccessoryEffect } from "./equipment-data.ts";
import { itemDirectory } from "./item-directories.ts";
import { rosterSlotOfCharId } from "./roster.ts";

export const EQUIPMENT_BY_ID: Record<number, EquipmentItem> = Object.fromEntries(EQUIPMENT.map(e => [e.id, e]));

export type EquipSlot = "head" | "body" | "right" | "left" | "acc0" | "acc1";
export const EQUIP_SLOTS: EquipSlot[] = ["head", "body", "right", "left", "acc0", "acc1"];

// state.equipment[partyIdx] = { head?: itemId, body?: itemId, ... }
export type EquipmentSlots = Partial<Record<EquipSlot, number>>;

/**
 * The slots an item's own WIELD DESCRIPTOR allows, not its catalog slot. The
 * equip-stat record's byte +0x2 indexes the eight-entry table at 0x8009a7c4:
 * 1 Right, 2 Left, 3 Left or Right, 4 Head, 5 Body, 6 Accessory, 7 Two-handed,
 * 8 Accessory (claim EQUIP-WIELD-DESCRIPTOR-2026-09-13; ststatus F0x800867b8).
 * Falls back to the catalog slot when the byte is absent.
 *
 * **7 (Two-handed) is BOTH hand rows** — that is the original's own admission
 * test, `F0x8009A344` (`ststatus.s:23980`-`:24029`, RAM 0x8009A344, service slot
 * `[0x8009B5F0]`): it refuses a descriptor-1 piece in row 3 and a descriptor-2
 * piece in row 2 and refuses nothing else, so a two-handed weapon is offered in
 * the left-hand list too. Both hand rows' candidate builders admit the same four
 * descriptors (`F0x80099FF8`'s four bytes at 0x8009B5F8 = 01 02 03 07). The
 * record a two-hander is then WRITTEN to is the same one either row: both hand
 * halfwords (`equipApplyRecord` below).
 */
export function wieldSlotsFor(item: EquipmentItem | undefined | null): EquipSlot[] {
  const idx = item?.statBytes?.[2];
  switch (idx) {
    case 1: return ["right"];
    case 2: return ["left"];
    case 3: return ["right", "left"];
    case 4: return ["head"];
    case 5: return ["body"];
    case 6:
    case 8: return ["acc0", "acc1"];
    case 7: return ["right", "left"];   // Two-handed: offered in BOTH hand lists
    default:
      if (item?.slot === "accessory") return ["acc0", "acc1"];
      return item?.slot ? [item.slot] : [];
  }
}

/** A Two-handed item (descriptor 7) occupies both hand halfwords. */
export function isTwoHanded(item: EquipmentItem | undefined | null): boolean {
  return item?.statBytes?.[2] === 7;
}

// ---------------------------------------------------------------------------
// The pause EQUIP page's ROW ADMISSION — one port, three callers.
//
// The original keeps it in two places inside pro/ststatus, and both were read
// against the disc's own bytes on 2026-10-04:
//
//   F0x8009A344  file 0x17694 (RAM 0x8009A344), service slot `[0x8009B5F0]`
//     `(member's roster slot, chosen row, item id)` → admitted or not.
//   F0x80099F84  file 0x16CD4, service slot `[0x8009B5EC]`
//     which ids a row's list is built from, dispatched on the six-word row table.
//   F0x80099FF8  the two hand rows' builder; F0x8009A1BC the head/body rows'.
//   F0x8008744C  file 0x4A7C-0x4B78 — the two passes that order the list.
//
// The six rows are the original's, in the original's order, and they are the
// same six names `EQUIP_SLOTS` already carries: head, body, right hand, left
// hand, accessory, accessory (`F0x8008744c` clamps the cursor to `0..5`,
// `ststatus.s:4745`-`:4770`, and its row label is text `0x31 + 14*row`).
//
// THE ROW TABLE — `ststatus` `0x8009A7E4`, file `0x17B34`, eight words read from
// `pro_ststatus.bin`: **6, 7, 5, 5, 4, 4**. That is not the five id
// directories; `F0x80099F84` reads it as a LIST BUILDER:
//
//   0..4  the shared resident directory (`F0x800135E8`, the five pointers at
//         `0x80042BC8`) — only the two accessory rows take this arm, and both
//         take kind 4, the accessories, whole;
//   5     `F0x80099FF8` — directories 2 then 3, keeping an id whose descriptor
//         is one of the four bytes at `0x8009B5F8` (**1 2 3 7**); this is what
//         BOTH hand rows ask for;
//   6     `F0x8009A1BC(4)` — directories 2 then 3, descriptor exactly 4 (head);
//   7     `F0x8009A1BC(5)` — directories 2 then 3, descriptor exactly 5 (body).
//
// The builder walks directory 2 (ids 92-214) before directory 3 (215-291), so
// every row's candidates come out in ascending id order. All three builders call
// the directory walker with a POSITIVE kind, so a piece only worn and not
// carried is not a candidate at all.
/** `ststatus` 0x8009A7E4 (file 0x17B34): each of the six rows' list builders. */
export const PAUSE_EQUIP_ROW_TABS: readonly number[] = [6, 7, 5, 5, 4, 4];

const PAUSE_EQUIP_ROW_FAMILIES: readonly (readonly number[])[] = [
  [4], [5], [1, 2, 3, 7], [1, 2, 3, 7], [6, 8], [6, 8],
];

/** The builders' own filter: would row `row` even COLLECT this piece? Rows 4 and 5
 *  are the one case where the builder applies none — `F0x80099F84` hands them
 *  directory 4 whole — and `[6, 8]` is that directory's whole content, so there
 *  the list is a no-op and only `equipItem` benefits from the check. */
export function pauseEquipRowCollects(row: number, itemId: number): boolean {
  const families = PAUSE_EQUIP_ROW_FAMILIES[row];
  if (!families) return false;
  return families.includes(EQUIPMENT_BY_ID[itemId]?.statBytes?.[2] as number);
}

/**
 * `F0x8009A344` (`ststatus.s:23980`-`:24004`) and nothing else — the original
 * runs it only over ids a row's builder already collected, so it does NOT know
 * which rows a descriptor belongs in:
 *
 *   * the item id `-1` is the list's take-off row and is always admitted
 *     (`beq $a0, $v0, .L0x00017720` → `li $v0, 1`);
 *   * the member's STARTER LINE must be in the record's wear mask — byte 4 read
 *     through the item record's word-0 pointer (`lbu $v0, 0x4($v1)` /
 *     `srav $v0, $v0, $s0` / `andi $v0, 1`, `ststatus.s:23995`-`:23999`);
 *   * descriptor 1 (Right) is refused in row 3 and descriptor 2 (Left) in row 2
 *     (`ststatus.s:24005`-`:24029`). Nothing else is refused — a Claymore passes
 *     this test in the HEAD row, which is why the builder above is a separate
 *     filter and `tests/lane-b/pause-equipment.test.js` pins this routine alone.
 *
 * `lineSlot` is the member's roster slot (`screen+0x5C`, written from
 * `rosterSlot(partyPosition)` in `F0x800882C8`); null means "unknown member",
 * which the original cannot express, so the mask test is skipped then.
 */
export function pauseEquipAdmitsRecord(
  row: number, descriptor: number | undefined, wearMask: number | undefined, lineSlot: number | null,
): boolean {
  if (wearMask == null) return false;
  if (lineSlot != null && ((wearMask >> (lineSlot & 31)) & 1) === 0) return false;
  if (descriptor === 1) return row !== 3;
  if (descriptor === 2) return row !== 2;
  return true;
}

/** `F0x8009A344` through the catalogue: may `lineSlot`'s member wear `itemId` in `row`? */
export function pauseEquipRowAdmits(lineSlot: number | null, row: number, itemId: number): boolean {
  if (itemId === -1) return true;
  const item = EQUIPMENT_BY_ID[itemId];
  return pauseEquipAdmitsRecord(row, item?.statBytes?.[2], item?.wearMask, lineSlot);
}

/** The whole question the player sees — does this row OFFER this piece? The
 *  builder's filter and the admission test, both. */
export function pauseEquipRowOffers(lineSlot: number | null, row: number, itemId: number): boolean {
  if (itemId === -1) return true;
  return pauseEquipRowCollects(row, itemId) && pauseEquipRowAdmits(lineSlot, row, itemId);
}

/**
 * `F0x80099F84` → `F0x800135E8` / `F0x80099FF8` / `F0x8009A1BC`: the ids row
 * `row`'s list is built from, in the order the original walks them
 * (directory 2 then 3, ascending id; the accessory rows are directory 4).
 * Only ids `isHeld` accepts are candidates — the builders call the directory
 * walker with a positive kind, so a worn-only piece is not listed.
 */
export function pauseEquipCandidateIds(row: number, isHeld: (id: number) => boolean): number[] {
  const tab = PAUSE_EQUIP_ROW_TABS[row] ?? 0;
  const kinds = tab >= 5 ? [2, 3] : [tab];
  const out: number[] = [];
  for (const kind of kinds) {
    for (const id of itemDirectory(kind) ?? []) {
      if (isHeld(id) && pauseEquipRowCollects(row, id)) out.push(id);
    }
  }
  return out;
}

/**
 * The whole list as the original shows it: `F0x8008744C` writes `-1` at the
 * list's first halfword unconditionally (`sh $v0, 0x78($s3)` with `li $v0, -1`,
 * `ststatus.s:24156`) — the take-off row is ALWAYS row 0, even on an empty slot
 * — then the admitted candidates in builder order, then the refused ones, which
 * the cursor cannot land on (`F0x8008744c` case 3's second pass, and
 * `F0x80086900`'s `unk138(row, 7)` for a refused row).
 */
export function pauseEquipListIds(
  lineSlot: number | null, row: number, isHeld: (id: number) => boolean,
): number[] {
  const yes: number[] = [];
  const no: number[] = [];
  for (const id of pauseEquipCandidateIds(row, isHeld)) {
    (pauseEquipRowAdmits(lineSlot, row, id) ? yes : no).push(id);
  }
  return [-1, ...yes, ...no];
}

function slotAccepts(slot: EquipSlot, item: EquipmentItem): boolean {
  const row = EQUIP_SLOTS.indexOf(slot);
  return row >= 0 && pauseEquipRowCollects(row, item.id)
    && pauseEquipAdmitsRecord(row, item.statBytes?.[2], item.wearMask, null);
}

// Shop gear-access bit test (claim EQUIP-C015-shop-gear-access-bitmask): a party
// Digimon may wear an item iff the bit for its STARTER LINE (0..7, from
// rosterSlotOfCharId) is set in the item's 8-bit wearMask (descriptor f3 & 0xff).
// Evolution is irrelevant. stitshop F0x8008c4cc; sweep-verified against live RAM
// for all 268 items (docs/research/ui/captures/shop-gear-access-mask-sweep-2026-09-09.txt).
export function gearAccessibleForLine(itemId: number, lineSlot: number): boolean {
  const item = EQUIPMENT_BY_ID[itemId];
  if (!item) return false;
  const mask = item.wearMask;
  if (mask == null) return true;            // non-gear / unknown => do not block
  if (lineSlot < 0 || lineSlot > 7) return false;  // not a partner line (matches F0x80016d94 idx<3 guard spirit)
  return ((mask >> lineSlot) & 1) === 1;
}

/** Shop slot choice from stitshop F0x8008c510. Null means this item cannot
 * replace the current pair; the caller still checks the member's wear mask. */
export function shopEquipSlot(equipment: EquipmentSlots, itemId: number): EquipSlot | null {
  const item = EQUIPMENT_BY_ID[itemId];
  if (!item?.statBytes) return null;
  const old = (slot: EquipSlot) => EQUIPMENT_BY_ID[equipment[slot] ?? -1];
  const word = (gear: EquipmentItem | undefined, offset: number) =>
    (gear?.statBytes?.[offset] ?? 0) | ((gear?.statBytes?.[offset + 1] ?? 0) << 8);
  switch (item.statBytes[2]) {
    case 1:
    case 7: return "right";
    case 2: return "left";
    case 4: return "head";
    case 5: return "body";
    case 3: {
      if (!equipment.right) return "right";
      if (!equipment.left) return "left";
      const right = old("right"), left = old("left");
      if (right?.statBytes?.[2] === 7) return "right";
      if (left?.family === 20 || !right || !left ||
          right.family < 2 || right.family > 14 || left.family < 2 || left.family > 14) return null;
      return word(right, 10) >= word(left, 10) ? "left" : "right";
    }
    case 6:
    case 8: {
      if (!equipment.acc0) return "acc0";
      if (!equipment.acc1) return "acc1";
      const first = old("acc0"), second = old("acc1");
      if (item.statBytes[2] === 8) {
        if (first?.statBytes?.[2] === 8 && first.statBytes[3] === item.statBytes[3]) return "acc0";
        if (second?.statBytes?.[2] === 8 && second.statBytes[3] === item.statBytes[3]) return "acc1";
      }
      return word(first, 6) >= word(second, 6) ? "acc1" : "acc0";
    }
    default: return null;
  }
}

/**
 * THE EQUIP-APPLY ROUTINE — one port, three callers.
 *
 * The disc has ONE such routine and three copies of it, all the same
 * instructions with a different register holding the chosen slot:
 *
 *   * `ststatus 0x8009A3E8` (file `0x17738`) — the pause STATUS page's EQUIP panel;
 *   * `stitshop F0x8008C800` (file `0x9B50`) — the merchant's EQUIP screen;
 *   * `ststatus` file `0x98B8`-`0x99E8` — a third full copy.
 *
 * Its four arms, and where each class test sits in the merchant's copy
 * (`stitshop.s:9981`-`:9990` displace, `:10002`-`:10006` hand pick, `:10039`/`:10054`
 * the accessory pair's byte-3 tests, `:10094`-`:10098` equip):
 *
 *   1. **displace** — `lh $a1, 0x3c0($s1)` reads the chosen slot
 *      (`$s1 = record + slot*2`, `$s3` is the wearer record). `beqz $a1` skips the
 *      whole arm when the slot is empty. Otherwise it counts the piece out
 *      (`worn -= 1` / `bag += 1`), then clears BOTH hands when the piece it just
 *      took off reads **7** (`sh $zr,0x3c4($s3)` + `sh $zr,0x3c6($s3)`, the second
 *      in the `j`'s delay slot) and only the chosen slot otherwise.
 *   2. **two-handed pick** — only when the NEW id is > 0 (`blez $s4` returns first)
 *      and it reads **7**. It takes the piece out of the RIGHT hand if that holds
 *      one, else out of the LEFT hand, else nothing, and counts each out exactly
 *      as arm 1 does.
 *   3. **accessory pair loop** — only when the new id is not 7 and reads **8**. It
 *      walks `+0x3C8` and `+0x3CA` for two iterations WITHOUT breaking, and takes
 *      a piece out when its own byte 3 equals the new item's byte 3 (its target
 *      code). Two matching accessories are two pieces back in the bag.
 *   4. **equip** — counts the new piece in (`worn += 1` / `bag -= 1`), then writes
 *      it: BOTH hand halfwords when it reads 7, else the one chosen slot.
 *
 * WHAT the class test reads — this is the correction that matters. All three tests
 * go through TWO steps, not one:
 *
 *     lui $v0, 0x8004 / lw $v0, 0x2b98($v0)   # the provider at [0x80042B98]
 *     jalr $v0                                # -> f5, 0x80041838 + 12*id
 *     lw $v1, ($v0)                           # word 0 of that item record: a POINTER
 *     lbu $v1, 0x2($v1)                       # byte 2 of the record it POINTS AT
 *
 * The byte is therefore the **equip-stat record's** byte 2 — the wield descriptor
 * (`EQUIP-WIELD-DESCRIPTOR-2026-09-13`), NOT the item record's own byte 2. The
 * item record's byte 2 is the catalogue category and reads 0/4/5 across the whole
 * id space; through the pointer the same byte reads 7 for the 23 ids 176-198 (the
 * big swords, halberds, bows and the Zweihander 178) and 8 for the 44 ids 316-359
 * (the behavioural accessories), so all three arms are LIVE. Census asserted
 * against the disc's own bytes in `tests/item-store-oracle.test.js`.
 *
 * Live confirmation: `docs/research/ui/captures/shop-heavyarmory-2026-09-10.md` —
 * buying the Zweihander 178 over a Buckler 275 in the left hand left
 * `+0x3C4 = 178` AND `+0x3C6 = 178`, the Buckler back in the bag, and the pause
 * sheet listing `Head / Body / Zweihander / Zweihander / Accessory / Accessory`.
 *
 * The COUNT is unaffected: each arm moves the worn byte once, arm 1 once however
 * many hands it cleared, arm 2 once, arm 4 once. A two-handed weapon is one worn
 * copy (`engine/dw3/item-store.ts` `commitRecord`).
 */
export function equipApplyRecord(
  equipment: EquipmentSlots, slot: EquipSlot, itemId: number,
): { next: EquipmentSlots; returned: number[] } {
  const next: EquipmentSlots = { ...equipment };
  const returned: number[] = [];
  // Arms 1 and 2 both clear a piece out of a slot the same way: a two-hander
  // gives up both hands, anything else only the slot it was named in.
  const takeOff = (target: EquipSlot) => {
    const id = Number(next[target]) || 0;
    if (!id) return;
    returned.push(id);
    if (isTwoHanded(EQUIPMENT_BY_ID[id])) {
      delete next.right;
      delete next.left;
    } else delete next[target];
  };
  takeOff(slot);                                   // arm 1: displace
  if (itemId > 0) {                                // arm 1's `blez` returns for an unequip
    const kind = EQUIPMENT_BY_ID[itemId]?.statBytes?.[2];
    if (kind === 7) {
      if (next.right) takeOff("right");             // arm 2: right hand first...
      else if (next.left) takeOff("left");          // ...else left, else nothing
      next.right = itemId;                          // arm 4: a two-hander takes both
      next.left = itemId;
    } else {
      if (kind === 8) {                             // arm 3: the accessory pair
        for (const target of ["acc0", "acc1"] as const) {
          const worn = EQUIPMENT_BY_ID[next[target] ?? -1];
          if (worn?.statBytes?.[3] === EQUIPMENT_BY_ID[itemId]?.statBytes?.[3]) {
            takeOff(target);
          }
        }
      }
      next[slot] = itemId;
    }
  }
  return { next, returned };
}

/** Apply `equipApplyRecord`'s record over `equipment` in place. */
function commitSlots(equipment: EquipmentSlots, next: EquipmentSlots): void {
  for (const key of EQUIP_SLOTS) delete equipment[key];
  for (const key of EQUIP_SLOTS) {
    const id = Number(next[key]) || 0;
    if (id > 0) equipment[key] = id;
  }
}

/** The slot writes and displaced items from stitshop F0x8008c800 — the merchant's
 * call of the shared `equipApplyRecord`, with the slot its own chooser picks
 * (F0x8008C510). Each displaced item appears once, including a two hand item
 * stored in both hands. */
export function shopEquipSwap(equipment: EquipmentSlots, itemId: number):
  { slot: EquipSlot; equipment: EquipmentSlots; displaced: number[] } | null {
  const slot = shopEquipSlot(equipment, itemId);
  const item = EQUIPMENT_BY_ID[itemId];
  if (!slot || !item?.statBytes) return null;
  const { next, returned } = equipApplyRecord(equipment, slot, itemId);
  return { slot, equipment: next, displaced: returned };
}

// Equip itemId from inventory into slot, returning the previously-equipped item (if any)
// so the caller can put it back in the inventory. Pure — caller owns inventory/equipment state.
//
// The record it writes is the shared `equipApplyRecord`, so the pause page and the
// merchant run the SAME port of the original's one routine: a two-handed weapon
// ends up named in BOTH hand halfwords, and a displaced two-hander frees both.
export function equipItem(
  equipment: EquipmentSlots, slot: EquipSlot, itemId: number, lineSlot?: number,
): { ok: boolean; msg?: string; replaced?: number; cleared?: number } {
  const item = EQUIPMENT_BY_ID[itemId];
  if (!item) return { ok: false, msg: "Not equipment." };
  if (!slotAccepts(slot, item)) return { ok: false, msg: "Can't equip there." };
  if (lineSlot != null && !gearAccessibleForLine(itemId, lineSlot)) {
    return { ok: false, msg: "Can't equip that." };
  }
  const replaced = equipment[slot];
  const { next, returned } = equipApplyRecord(equipment, slot, itemId);
  commitSlots(equipment, next);
  // `replaced` is the piece arm 1 took out of the chosen slot; `cleared` is a piece
  // one of the other arms took off, so the caller can return every one to the bag.
  const others = returned.filter((id) => id !== replaced);
  const out: { ok: boolean; replaced?: number; cleared?: number } = { ok: true };
  if (replaced != null) out.replaced = replaced;
  const cleared = others.at(-1);
  if (cleared != null) out.cleared = cleared;
  return out;
}

/** The routine's `blez $s4` return: the displace arm alone, nothing put on. A
 * two-hander taken off the right hand therefore frees both hands and returns one
 * copy, which is what the original does (`sh $zr,0x3c4` + `sh $zr,0x3c6`). */
export function unequipItem(equipment: EquipmentSlots, slot: EquipSlot): number | undefined {
  const prev = equipment[slot];
  const { next } = equipApplyRecord(equipment, slot, 0);
  commitSlots(equipment, next);
  return prev;
}

// ---------------------------------------------------------------------------
// What a piece of gear does to the displayed stats.
//
// stitshop F0x80088a64 builds the party card's before/after stat blocks and
// F0x80088db8 is its one adder, `add(buf, code, amount)`:
//   code 7      -> amount into ALL SIX core stats (six separate clamped adds)
//   code 1..6   -> amount into core stat (code-1) of the block
//   code 8..14  -> amount into elemental resist (code-8)
//   anything else (e.g. the 17..21 status-resist codes) -> no stat line at all
// and F0x80088a64 walks the six equip slots, resolving each item's Unknown1
// record, reading its family byte at +0x9 and the item's stat record pointer at
// +0x0, and then applying these offsets of THAT record — where what an offset
// means depends on the family, which is why the catalog ships raw bytes:
//   family  2..14 (weapons)   : POW  += u16 @+0x0A; pairs (@+0x0C code, s16 @+0x06)
//                                          and (@+0x0D code, s16 @+0x08)
//   family 15..20 (armour)    : DEF  += u16 @+0x0C; pairs (@+0x0A code, s16 @+0x06)
//                                          and (@+0x0B code, s16 @+0x08)
//   family 21..24 (accessories): pair  (@+0x08 code, s16 @+0x06)
//   all three                 : CHR  += u16 @+0x00
// Each add is a u16 store clamped to 999 when the signed value reaches 1000.
// Claim EQUIP-C016-shop-gear-stat-contributions. Its caller F0x80089274 decides
// which two of these are the card's fixed rows: see gearPrimaryStat /
// gearCodedStat and engine/systems/equip-preview.ts.
export const GEAR_CORE_STATS = ["str", "def", "spt", "wis", "spd", "chr"] as const;
export const GEAR_ELEMENTS =
  ["fire", "water", "ice", "wind", "thunder", "machine", "dark"] as const;

export interface GearStatContribution {
  /** "str"|"def"|"spt"|"wis"|"spd"|"chr"|"elem_<element>" */
  stat: string;
  amount: number;
}

const byteAt = (b: number[], o: number) => b[o] ?? 0;
const u16At = (b: number[], o: number) => byteAt(b, o) | (byteAt(b, o + 1) << 8);
const s16At = (b: number[], o: number) => (u16At(b, o) << 16) >> 16;

/** The stat a record's stat CODE byte names, as F0x80088db8's three branches read it:
 *  1..6 = a core stat, 7 = all six at once, 8..14 = an elemental resist. Anything else
 *  (including the 17..21 status-resist codes) names no stat and moves no number. */
export function gearStatForCode(code: number, amount: number): GearStatContribution[] {
  if (code === 7) return GEAR_CORE_STATS.map((stat) => ({ stat, amount }));
  if (code >= 1 && code <= 6) {
    const stat = GEAR_CORE_STATS[code - 1];
    return stat ? [{ stat, amount }] : [];
  }
  if (code >= 8 && code <= 14) {
    const el = GEAR_ELEMENTS[code - 8];
    return el ? [{ stat: `elem_${el}`, amount }] : [];
  }
  return [];
}

/** The stat CODE byte stitshop F0x80089274 puts on row 1 of an accessory card, or null
 *  when it names no single stat (the game hides that row instead). Codes 1..5 and 8..14
 *  only: 6 would repeat the Charisma row and 7 would move six stats at once. */
export function gearCodedStat(item: EquipmentItem): string | null {
  const code = item.statBytes ? byteAt(item.statBytes, 0x08) : 0;
  if ((code - 1) >>> 0 < 5) return GEAR_CORE_STATS[code - 1] ?? null;
  if ((code - 8) >>> 0 < 7) {
    const el = GEAR_ELEMENTS[code - 8];
    return el ? `elem_${el}` : null;
  }
  return null;
}

/** The item's stat-record byte offsets, as stitshop F0x80088a64 reads them. */
export function gearStatContributions(item: EquipmentItem): GearStatContribution[] {
  const b = item.statBytes;
  if (!b) return [];
  const out: GearStatContribution[] = [];
  const add = (code: number, amount: number) => out.push(...gearStatForCode(code, amount));
  const fam = item.family;
  if (fam >= 2 && fam <= 14) {
    add(1, u16At(b, 0x0a));
    add(byteAt(b, 0x0c), s16At(b, 0x06));
    add(byteAt(b, 0x0d), s16At(b, 0x08));
  } else if (fam >= 15 && fam <= 20) {
    add(2, u16At(b, 0x0c));
    add(byteAt(b, 0x0a), s16At(b, 0x06));
    add(byteAt(b, 0x0b), s16At(b, 0x08));
  } else if (fam >= 21 && fam <= 24) {
    add(byteAt(b, 0x08), s16At(b, 0x06));
  } else {
    return [];
  }
  add(6, u16At(b, 0x00));
  return out;
}

/** Which family's card layout an item gets — the shop's two fixed rows.
 *  A family 21-24 accessory leads with Charisma and shows its own coded stat second;
 *  a family 2-14 weapon leads with POW and any other gear leads with DEF. */
export function gearPrimaryStat(item: EquipmentItem): "str" | "def" {
  return item.family >= 2 && item.family <= 14 ? "str" : "def";
}

// Sum of equipped bonuses across all 6 slots: the displayed stat changes of
// `gearStatContributions`, the two battle pools (+0x3a to-hit / +0x3b to-evade,
// claim EQUIP-C009), and the decoded accessory effects
// (accessory-effects-decoded-2026-07-10.md) that are NOT stats — status rings
// (which move no stat line on the card) and the behavioral
// crests/adapters/proxies/powers the battle engine hooks.
export interface EquipmentBonuses {
  str: number; def: number; spt: number; wis: number; spd: number; chr: number;
  /** Elemental damage-taken reduction, folded into elemBonuses (points). */
  elemResists: Record<string, number>;
  /** Status-infliction resistance (poison/paralyze/confuse/sleep/ko, points). */
  statusResists: Record<string, number>;
  /** Combatant +0x3a: accumulated to-hit contribution of the worn gear. */
  accPool: number;
  /** Combatant +0x3b: accumulated to-evade contribution of the worn gear. */
  evadePool: number;
  /** Behavioral accessory effects, deduped per equipped item. */
  effects: AccessoryEffect[];
  /** The roster slot the set bonus was resolved for, when one was given. */
  signatureSet?: number | null;
}

// The game's own add: a u16 store that saturates at 999 once the signed value
// reaches 1000 (F0x80088db8's `sll 0x10 / sra 0x10 / slti 0x3e8` sequence).
function equipAdd(cur: number, amount: number): number {
  const v = (cur + amount) & 0xffff;
  return ((v << 16) >> 16) >= 1000 ? 999 : (v << 16) >> 16;
}

export function equipmentBonuses(
  equipment: EquipmentSlots,
  rosterSlot?: number | null,
): EquipmentBonuses {
  const out: EquipmentBonuses = {
    str: 0, def: 0, spt: 0, wis: 0, spd: 0, chr: 0,
    elemResists: {}, statusResists: {}, accPool: 0, evadePool: 0, effects: [],
  };
  // F0x8009ec94 (and the shop's F0x80088a64) walk the six equipment slots in
  // their stored order. This is observable for status rings: acc0 is applied
  // before acc1, and a matching status-resistance target is assigned rather
  // than accumulated.
  for (const slot of EQUIP_SLOTS) {
    const itemId = equipment[slot];
    if (itemId == null) continue;
    const item = EQUIPMENT_BY_ID[itemId];
    if (!item) continue;
    for (const c of gearStatContributions(item)) {
      if (c.stat.startsWith("elem_")) {
        const el = c.stat.slice(5);
        out.elemResists[el] = equipAdd(out.elemResists[el] ?? 0, c.amount);
      } else {
        out[c.stat as "str"] = equipAdd(out[c.stat as "str"], c.amount);
      }
    }
    out.accPool += item.accPool ?? 0;
    out.evadePool += item.evadePool ?? 0;
    const eff = item.effect;
    if (!eff) continue;
    if (eff.kind === "status_resist" && eff.status) {
      out.statusResists[eff.status] = eff.amount;
    } else if (eff.kind !== "stat" && eff.kind !== "elem_resist") {
      out.effects.push(eff);
    }
  }
  // F0x80017174's tail: the four-piece signature set for this roster slot, added
  // AFTER the per-item fold and with no cap of its own (exe/fns.s:7959-7996).
  const set = signatureSetBonus(rosterSlot ?? null, equipment);
  for (const c of set ?? []) {
    if (c.stat.startsWith("elem_")) continue;
    out[c.stat as "str"] += c.amount;
  }
  return out;
}

// ── Signature-weapon secondary effects ──────────────────────────────────────
// Decoded 2026-09-13 (claims equip-signature-weapon-gate-map-2026-09-13 and
// equip-weapon-status-applier-crossref-2026-09-13). The equipment-init ladder
// (FIGHTSTG_F0x8009ec94) writes the weapon record's +0x10/+0x11 into the
// attacker's effective-stat block; the move resolver F0x8009e0cc then gates one
// applier per odd byte, and those appliers are the canonical f7 status kinds:
//   +0x2d poison, +0x2f frozen, +0x31 confuse, +0x33 instant-death, +0x35 drain.
// The odd byte is the proc power (f9[0]); the even byte is the magnitude/ratio
// (f9[1]). This is the item-id -> pair map read from the ladder's comparisons.
export type WeaponSecondaryKind = "poison" | "frozen" | "confuse" | "ko" | "drain";
export interface WeaponSecondary { kind: WeaponSecondaryKind; proc: number; value: number; }

/**
 * The signature-weapon ladder of `FIGHTSTG_F0x8009ec94`, as decoded data — every
 * ItemId the four weapon/armour halfwords compare against, with the effective
 * bytes it writes. Transcribed 2026-10-04 from `pro/fightstg.s` lines
 * 29436-29500 (`li $v0, 0x97` … `li $v0, 0xbf`); it is a data list because the
 * assembly is one chained compare ladder whose constants sit in the *previous*
 * rung's branch delay slot, which is why reading it as one pair per physical
 * block shifts the whole map.
 *
 * `kind` is what the written bytes MEAN, taken from the appliers that consume
 * them (F0x8009e0cc's dispatch): `+0x2d/+0x2e` poison, `+0x2f/+0x30` frozen,
 * `+0x31/+0x32` confuse, `+0x33/+0x34` instant-KO, `+0x35/+0x36` drain.
 * `+0x38` is the Search-Crest crit byte, so the last two rungs are a CRIT
 * contribution, not a status proc — and they set the ladder's `found` flag,
 * which suppresses the Multi/Search/Counter crest rungs below.
 *
 * NOTE (corrects the pre-2026-10-04 hand map): item 150 SaberFang is NOT a
 * drain weapon. The ladder's drain rung tests 0x5e/0x93/0xad = 94 CrimsonBlade
 * / 147 CerberusFang / 173 VampireLance, and 0x96/0xbf = 150 SaberFang /
 * 191 Shuriken write the crit byte instead. CrimsonBlade was missing entirely.
 */
export interface WeaponLadderRung {
  ids: readonly number[];
  /** Effective-byte pair the rung writes, or null when it writes none. */
  bytes: readonly [number, number] | null;
  kind: WeaponSecondaryKind | "crit";
  asm: string;
}

export const WEAPON_LADDER: readonly WeaponLadderRung[] = [
  { ids: [151], bytes: [0x2d, 0x2e], kind: "poison", asm: "0x8009f100 `li $v0, 0x97`" },
  { ids: [210], bytes: [0x2f, 0x30], kind: "frozen", asm: "0x8009f108 `li $v0, 0xd2`" },
  { ids: [180, 194], bytes: [0x31, 0x32], kind: "confuse", asm: "0x8009f12c `li $v0, 0xb4` / 0x8009f150 `li $v0, 0xc2`" },
  { ids: [109, 186], bytes: [0x33, 0x34], kind: "ko", asm: "0x8009f158 `li $v0, 0x6d` / 0x8009f17c `li $v0, 0xba`" },
  { ids: [94, 147, 173], bytes: [0x35, 0x36], kind: "drain", asm: "0x8009f184 `li $v0, 0x5e` / 0x8009f1a8 `li $v0, 0x93` / 0x8009f1b0 `li $v0, 0xad`" },
  { ids: [150, 191], bytes: null, kind: "crit", asm: "0x8009f1b8 `li $v0, 0x96` / 0x8009f1dc `li $v0, 0xbf` -> `sb $v0, 0x38($s2)`" },
];

/** Every ItemId the signature-weapon ladder compares, with its rung. */
export const WEAPON_LADDER_BY_ID: Record<number, WeaponLadderRung> =
  Object.fromEntries(WEAPON_LADDER.flatMap((r) => r.ids.map((id) => [id, r])));

/** The crit byte (effective `+0x38`) a weapon contributes, or 0. SaberFang and
 *  Shuriken are the only two weapons the ladder routes there; the value is their
 *  own stat record's byte `+0x11`, the same byte Search Crest supplies. */
export function weaponCritByte(weaponId: number | null | undefined): number {
  if (weaponId == null) return 0;
  const rung = WEAPON_LADDER_BY_ID[weaponId];
  if (!rung || rung.kind !== "crit") return 0;
  return EQUIPMENT_BY_ID[weaponId]?.statBytes?.[17] ?? 0;
}

/**
 * Whether a worn weapon suppresses the three crest rungs. The signature-weapon
 * ladder sets its own `found` flag on ANY of the four weapon/armour halfwords it
 * tests (`pro/fightstg.s:29521 .L0x8009f204: bnez $s3, .L0x8009f29c`), and the
 * Multi/Search/Counter crest loop is gated on that flag being clear
 * (`:29521 .L0x8009f204: bnez $s3, .L0x8009f29c`). So in the original a partner
 * holding ANY signature weapon gets no Multi Crest, Search Crest or Counter Crest
 * at all, whatever the accessory slots say. The ladder steps over the second of
 * the four worn halfwords (`SIGNATURE_LADDER_SLOTS`), so a body piece never
 * counts.
 */
export function crestSuppressedByWeapon(equipment: EquipmentSlots): boolean {
  for (const slot of SIGNATURE_LADDER_SLOTS) {
    const id = equipment[slot];
    if (id != null && WEAPON_LADDER_BY_ID[id]) return true;
  }
  return false;
}

/** The worn halfwords the signature-weapon ladder walks, in the original's order:
 *  roster +0x3C0, +0x3C2, +0x3C4, +0x3C6, with the SECOND one stepped over
 *  (`pro/fightstg.s:29498 .L0x8009f0cc li $v0, 0x1` / `:29502 beq $s1, $v0,
 *  .L0x8009f1f4`). So a body piece is never a signature weapon. */
export const SIGNATURE_LADDER_SLOTS = ["head", "right", "left"] as const;

/** The on-hit secondary a signature weapon carries, or null when it has none
 *  (or its proc byte is zero, e.g. ShockHorn). `proc` is the f9[0] gate;
 *  `value` is f9[1]. */
export function weaponSecondary(weaponId: number | null | undefined): WeaponSecondary | null {
  const rung = weaponId == null ? undefined : WEAPON_LADDER_BY_ID[weaponId];
  if (!rung || rung.kind === "crit") return null;
  const item = weaponId == null ? undefined : EQUIPMENT_BY_ID[weaponId];
  if (!item) return null;
  const proc = item.statBytes?.[16] ?? 0;
  const value = item.statBytes?.[17] ?? 0;
  if (!proc) return null;
  return { kind: rung.kind as WeaponSecondaryKind, proc, value };
}

// ── The accessory ladder and every accessory code's decided consumer ─────────
// FIGHTSTG_F0x8009ec94's accessory pass walks roster halfwords +0x3C8 and +0x3CA
// (two iterations each) and writes the per-combatant effective-stat block at
// 0x800A4580 (enemy) / 0x800A45C0 (player), 0x40 bytes, memset each time.
//
// The id tests are a chain whose comparison constant is computed in the
// PREVIOUS rung's branch delay slot and masked by the next rung's
// `andi $v0, 0xffff`, so each rung tests `(id - base) & 0xffff < 2` for a
// two-item pair — the reading every consumer below agrees with (claims
// EQUIP-C008 / EQUIP-C031).
//
// `op` is how the byte is written: "add" accumulates (two of a kind stack),
// "set" overwrites (the second slot wins).
export interface AccessoryLadderRung {
  ids: readonly number[];
  effect: string;
  /** Effective-block byte written, or null when the rung writes none. */
  byte: number | null;
  op: "add" | "set";
  asm: string;
}

