// ── The worn family bytes: effective +0x28 / +0x29 / +0x2A ───────────────────────────
// `FIGHTSTG_F0x8009ec94`'s head/body/right/left pass (0x8009f018..0x8009f0c0) walks the
// four worn halfwords in that order. A family 2..14 piece ADDS its stat-record byte
// `+0x0E` to the to-hit pool (`0x8009f068`) and, when its byte `+0x12` is >= 2, stores
// that byte at the running index `s4` (`0x8009f080`) — the block's `+0x28`, `+0x29`, and
// (for a third such piece) `+0x2A`. A family 15..24 piece instead ADDs its byte `+0x10`
// to the to-evade pool (`0x8009f0b0`).
//
// The only consumer is `FIGHTSTG_F0x8009f6dc` stage 2 (0x8009f77c..0x8009f7a8): on a
// plain attack (`skill+0x9 < 2`) it scans `+0x28..+0x2A` (`slti $v0, $v1, 0x3`) for a
// byte `>= 2` equal to the defender's `+0x25` and ADDS half the running damage
// (0x8009f764: half, then the jump's delay slot `addu $s0, $v0`), a x1.5 bonus. So a
// signature weapon strengthens a plain attack against the one family it is built for —
// Dramon Guard and Dramon Horn carry 11, which is the Paildramon/Imperialdramon line.
const WORN_FAMILY_PASS_SLOTS = ["head", "body", "right", "left"] as const;

/**
 * The block's `+0x28..`: the stat-record byte `+0x12` of every worn family 2..14
 * piece that carries one, in the original's slot order. The damage tail
 * reads. The pass stores one byte per qualifying piece with no cap (0x8009f088
 * `addiu $s4, 0x1`), so this returns up to four; the damage tail reads the first three.
 */
export function wornFamilyBytes(equipment: EquipmentSlots | null | undefined): number[] {
  const eq = equipment ?? {};
  const out: number[] = [];
  for (const slot of WORN_FAMILY_PASS_SLOTS) {
    const id = eq[slot];
    if (id == null) continue;
    const item = EQUIPMENT_BY_ID[id];
    if (!item || item.family < 2 || item.family > 14) continue;
    const tag = item.statBytes?.[0x12] ?? 0;
    if (tag >= 2) out.push(tag);
  }
  return out;
}

// ── The signature set: the fourth worn piece that makes a set ────────────────
// `F0x80017174`'s tail (the producer of the block's five core stats, called through the
// save context's `+0x2734` slot that F0x8009ec94 uses as `copy_partner_stats`):
//
//     .L0x800174ac  addiu $v0, %lo(D0x8004b53c)   # the per-slot set: four i16 ids
//     .L0x800174b8  lh   $v1, ($s6)               # the worn roster +0x3C0..+0x3C6
//     .L0x800174bc  lh   $v0, ($a0)               # the set's four ids
//     ...four compares, each bneq -> .L0x80017548 (return)
//     .L0x80017508  lui  $v0, %hi(D0x8004b57c)   # then six u16 bonuses, added RAW
//     .L0x80017528  lhu  $v0, 0xc($a0)            # (no 999 clamp on this pass)
//
// So the bonus lands only when all FOUR of head/body/right/left match the slot's set,
// and it is added AFTER the 999 clamp of the per-item fold, so a set can carry a stat
// past 999. The table is the resident data at 0x8004B53C (8 slots x 8 bytes) followed by
// 0x8004B57C (8 slots x 12 bytes); `web/assets/data/pause/resident.bin` carries the same
// 0xA0 bytes at offset 7992 and the census test compares the two.
export const SIGNATURE_SET_SLOT_COUNT = 8;
/** Head, body, right, left ids per roster slot, from 0x8004B53C. */
export const SIGNATURE_SETS: readonly (readonly [number, number, number, number])[] = [
  [243, 269, 98, 284],    // slot 0 Ronin
  [242, 258, 112, 285],   // slot 1 Wild
  [222, 256, 124, 282],   // slot 2 Sniper
  [244, 271, 163, 286],   // slot 3 Brave
  [211, 268, 203, 288],   // slot 4 Dramon
  [245, 270, 149, 287],   // slot 5 Hazard
  [221, 257, 137, 283],   // slot 6 YinYang
  [232, 255, 136, 281],   // slot 7 Divine
];
/** The six-word bonus (STR, DEF, SPT, WIS, SPD, CHR) per roster slot, from 0x8004B57C. */
export const SIGNATURE_SET_BONUSES: readonly (readonly [number, number, number, number, number, number])[] = [
  [4, 4, 4, 4, 4, 20],
  [10, 10, 0, 0, 0, 20],
  [10, 0, 0, 0, 10, 20],
  [0, 10, 10, 0, 0, 20],
  [10, 0, 0, 10, 0, 20],
  [0, 0, 0, 10, 10, 20],
  [10, 0, 10, 0, 0, 20],
  [0, 10, 0, 10, 0, 20],
];

/** The four worn ids the set compares, in the original's order (roster +0x3C0..+0x3C6). */
export const SIGNATURE_SET_SLOTS = ["head", "body", "right", "left"] as const;

/**
 * The set bonus a member earns, as the six core-stat contributions it adds, or null
 * when the four worn ids are not the slot's set. `slot` is the roster slot
 * (`rosterSlotOfCharId`), because the original's table is indexed by the slot the
 * save context handed `F0x80017174`, not by the party position.
 *
 * The values are added UNCLAMPED, which is what `F0x80017174`'s tail does — its six-word
 * loop has no `slti 0x3e8` test, unlike the per-item fold above it.
 */
export function signatureSetBonus(
  slot: number | null | undefined,
  equipment: EquipmentSlots | null | undefined,
): GearStatContribution[] | null {
  if (slot == null) return null;
  const set = SIGNATURE_SETS[slot];
  const bonus = SIGNATURE_SET_BONUSES[slot];
  if (!set || !bonus) return null;
  const eq = equipment ?? {};
  for (let i = 0; i < SIGNATURE_SET_SLOTS.length; i++) {
    const slotKey = SIGNATURE_SET_SLOTS[i] as EquipSlot;
    if ((eq[slotKey] ?? 0) !== set[i]) return null;
  }
  return bonus
    .map((amount, i) => ({ stat: GEAR_CORE_STATS[i] ?? "str", amount }))
    .filter((c) => c.amount !== 0);
}

/**
 * Every accessory effect the shipped item data carries, with the consumer that
 * was located for it in the original and the walker's decision. The census test
 * `tests/equipment-effects-census.test.js` requires one entry per effect kind in
 * `equipment.json`, so a newly decoded effect cannot be added without saying
 * where it is read.
 */
export interface AccessoryEffectDecision {
  kind: string;
  status: "ported" | "vestigial" | "not_portable";
  consumer: string;
  /** The block byte the value reaches, when the effect is read by F0x8009ec94 itself.
   *  `null` when it arrives through the producer instead (F0x80017174), and when it is
   *  read by its own overlay off the roster halfwords. */
  blockByte?: number | null;
  note: string;
}

