/**
 * The walker's cached bonus block for the LEAD, refreshed from the lead's worn gear.
 *
 * `state.partnerStats.equipBonuses` is a cache: the battle, the STATUS sheet and the
 * merchant's preview all read it instead of walking the six slots again. Every path
 * that changes the lead's gear refreshes it through this one function — the pause page
 * (`commitPauseClose`), the legacy pause panel (web/menu.js) and the merchant
 * (web/shop*.js) — so the cache cannot go stale on one route and not another.
 */
export function syncLeadEquipBonuses(
  state: { partnerStats?: Record<string, unknown> | null; equipment?: unknown; party?: unknown; charId?: unknown },
  storage?: { setItem(key: string, value: string): void } | null,
): void {
  if (!state?.partnerStats) return;
  const equipment = (Array.isArray(state.equipment) ? state.equipment[0] : undefined) ?? {};
  // The signature set is keyed by the lead's ROSTER slot, so the cache has to know
  // which partner position 0 is — `party[0]`, falling back to the selected character.
  const party = Array.isArray(state.party) ? state.party : [];
  const leadCharId = String(party[0] ?? state.charId ?? "");
  state.partnerStats.equipBonuses = equipmentBonuses(equipment as EquipmentSlots, rosterSlotOfCharId(leadCharId));
  // No argument means "the browser's own storage", which is what every walker's equip
  // path wants; node callers pass their own shim or null.
  const store = storage === undefined
    ? (globalThis as { localStorage?: { setItem(key: string, value: string): void } }).localStorage ?? null
    : storage;
  store?.setItem("partnerStats", JSON.stringify(state.partnerStats));
}
